    const node=e=>e?{tag:e.tagName,id:e.id||null,class:typeof e.className==='string'?e.className:null,text:(e.innerText||e.textContent||'').trim().slice(0,110),box:rect(e),styles:style(e)}:null;
    const hits=(x,y)=>({x,y,elementFromPoint:node(document.elementFromPoint(x,y)),stack:document.elementsFromPoint(x,y).slice(0,8).map(node)});
    const sample=reason=>{const e=document.querySelector('#runAssignSearch'),b=rect(e);const x=b?b.x+b.width/2:null,y=b?b.y+b.height/2:null;const ix=b?(Math.max(0,b.left)+Math.min(innerWidth,b.right))/2:null,iy=b?(Math.max(0,b.top)+Math.min(innerHeight,b.bottom))/2:null;const ancestors=[];for(let a=e?.parentElement;a&&ancestors.length<7;a=a.parentElement)ancestors.push(node(a));const activeAnimations=document.getAnimations().map(a=>({id:a.id,playState:a.playState,currentTime:a.currentTime,playbackRate:a.playbackRate,target:node(a.effect?.target),timing:a.effect?.getComputedTiming(),keyframes:a.effect?.getKeyframes?.()}));return{reason,index:state.frames++,UTC:new Date().toISOString(),performanceNow:performance.now(),timeOrigin:performance.timeOrigin,button:node(e),connected:e?.isConnected,disabled:e?.disabled,ariaDisabled:e?.getAttribute('aria-disabled'),buttonHovered:e?.matches(':hover'),buttonFocused:e===document.activeElement,focus:node(document.activeElement),hoverChain:Array.from(document.querySelectorAll(':hover')).slice(-8).map(node),scroll:{x:scrollX,y:scrollY},viewport:{width:innerWidth,height:innerHeight,documentWidth:document.documentElement.scrollWidth},centerHit:b?hits(x,y):null,visibleIntersectionHit:b?hits(ix,iy):null,lastPointerHit:state.pointer?hits(state.pointer.x,state.pointer.y):null,ancestors,activeAnimations,overlays:Array.from(document.querySelectorAll('dialog[open],[role="dialog"],[aria-modal="true"],.modal.open')).map(node)}};
    const send=payload=>state.pending.push(window.__uatAssignFramesToHost(payload));
    const event=ev=>{if('clientX'in ev)state.pointer={x:ev.clientX,y:ev.clientY};if(ev.type!=='pointermove'){const q={type:ev.type,UTC:new Date().toISOString(),performanceNow:performance.now(),clientX:ev.clientX,clientY:ev.clientY,target:node(ev.target),trusted:ev.isTrusted};state.events.push(q);send({kind:'event',...q})}};
    for(const name of ['pointermove','pointerdown','pointerup','click','focusin','focusout'])document.addEventListener(name,event,true);
    const frame=()=>{if(!state.running)return;state.buffer.push(sample('requestAnimationFrame'));if(state.buffer.length>=30)send({kind:'frames',frames:state.buffer.splice(0)});state.raf=requestAnimationFrame(frame)};
    state.buffer.push(sample('before-click'));state.raf=requestAnimationFrame(frame);
    state.stop=async()=>{state.running=false;cancelAnimationFrame(state.raf);for(const name of ['pointermove','pointerdown','pointerup','click','focusin','focusout'])document.removeEventListener(name,event,true);state.buffer.push(sample('after-click-or-error'));send({kind:'frames',frames:state.buffer.splice(0)});const writes=await Promise.allSettled(state.pending);return{startUTC:state.startUTC,endUTC:new Date().toISOString(),elapsedMs:performance.now()-state.start,frameCount:state.frames,events:state.events,hostWriteFailures:writes.filter(q=>q.status!=='fulfilled').length}};
    window.__uatAssignObservation=state;return{startUTC:state.startUTC,selector:'#runAssignSearch',instrumentation:'Read-only rAF geometry/styles/animations/focus/hover/hit-stack; no DOM/style/business mutation',noForce:true,timeoutMs:15000};
  });
  log('assign-search-first-start',start);let failure=null;
  try{await p.locator('#runAssignSearch').click()}catch(e){failure=e}
  let observation;try{observation=await p.evaluate(()=>window.__uatAssignObservation.stop())}catch(e){observation={collectionError:e.message}}
  const result={productSHA:'fbb98944a4bcee439e4e81ebfe3ef710bee4a3d0',...start,...observation,clickCalls:assignSearchClickCount,outcome:failure?'FAIL — first failure retained':'NOT REPRODUCED',rootCause:'UNKNOWN; no root-cause-fixed claim',error:failure?{message:failure.message,stack:failure.stack}:null,method:'One normal locator.click(), original15second timeout, no force/no retry/no fixed wait. Screenshot before and after. Full suite runs concurrently as in prior first-attempt context.'};
  fs.writeFileSync(root+'assign-search-first-result.json',JSON.stringify(result,null,2));log('assign-search-first-result',result);await shot(failure?'SEARCH-first-FAILED':'SEARCH-first-after');if(failure)throw failure;
